import { products, intent, installOwnedCartHooks, selectAndAdd, assertCart } from '../../support/cart';

describe('Isolated guest product-to-cart handoff', () => {
  const registerOwned = installOwnedCartHooks();
  it('CART-H01 — settled desktop default selection reaches the cart intact', () => {
    cy.viewport(1366, 900);
    const selected = intent(products.blackFriday, products.blackFriday.default, 2);
    selectAndAdd(selected, registerOwned);
    assertCart([selected]);
  });
  it('CART-H02 — narrow visible Add transfers the alternate package and quantity', () => {
    cy.viewport(390, 844);
    const selected = intent(products.blackFriday, products.blackFriday.alternate, 2);
    selectAndAdd(selected, registerOwned, 'narrow');
    assertCart([selected]);
  });
  it('CART-H03 — adding another product preserves both intended configurations', () => {
    cy.viewport(1366, 900);
    const first = intent(products.blackFriday, products.blackFriday.default, 2);
    const second = intent(products.simple, products.simple.default, 1);
    selectAndAdd(first, registerOwned); assertCart([first]);
    selectAndAdd(second, registerOwned); assertCart([first, second]);
  });
  it('CART-H04 — different packages of one product retain distinct quantities', () => {
    cy.viewport(1366, 900);
    const first = intent(products.blackFriday, products.blackFriday.default, 2);
    const second = intent(products.blackFriday, products.blackFriday.alternate, 1);
    selectAndAdd(first, registerOwned); assertCart([first]);
    selectAndAdd(second, registerOwned); assertCart([first, second]);
  });
});
